'use client';

import { useEffect, useState } from 'react';
import Link from 'next/link';
import { usePathname } from 'next/navigation';
import api, { authApi } from '@/lib/api';
import { User } from '@/lib/types';

const NAV_ITEMS: { label: string; href: string }[] = [
  { label: 'Dashboard', href: '/dashboard' },
  { label: 'Habits', href: '/habits' },
  { label: 'Calendar', href: '/calendar' },
  { label: 'Portal', href: '/portal' },
  { label: 'Boss Fight', href: '/boss-fight' },
  { label: 'Checklist', href: '/checklist' },
];

export function AppHeader() {
  const pathname = usePathname();
  const [user, setUser] = useState<User | null>(null);
  const [balance, setBalance] = useState<number | null>(null);
  const [balanceLoading, setBalanceLoading] = useState(true);

  useEffect(() => {
    let active = true;

    const loadProfile = async () => {
      try {
        const data: User = await authApi.getProfile();
        if (active) setUser(data);
      } catch {
        if (active) setUser(null);
      }
    };

    const loadBalance = async () => {
      try {
        const response = await api.get<{ balance: number }>('/fragments/balance');
        if (active) setBalance(response.data.balance);
      } catch {
        if (active) setBalance(null);
      } finally {
        if (active) setBalanceLoading(false);
      }
    };

    loadProfile();
    loadBalance();

    return () => {
      active = false;
    };
  }, []);

  const initial = user?.nombre?.trim()?.charAt(0)?.toUpperCase() || '?';

  return (
    <header
      className="w-full"
      style={{
        background: 'var(--panel)',
        borderBottom: '1px solid var(--panel-edge)',
      }}
    >
      <div className="max-w-6xl mx-auto px-4 pt-4">
        {/* Top row: greeting + fragments/avatar */}
        <div className="flex items-center justify-between gap-4">
          <p
            className="font-display text-lg sm:text-xl"
            style={{ color: 'var(--parchment)' }}
          >
            Bienvenido, <span style={{ color: 'var(--gold)' }}>{user?.nombre ?? '—'}</span>
          </p>

          <div className="flex items-center gap-4">
            {/* Fragments balance */}
            <div
              className="flex items-center gap-1.5 text-sm"
              style={{ color: 'var(--parchment)' }}
              title="Fragmentos"
            >
              <svg
                width="18"
                height="18"
                viewBox="0 0 24 24"
                fill="none"
                aria-hidden="true"
              >
                <path
                  d="M6 3h12l3 6-9 12L3 9l3-6Z"
                  stroke="var(--gold)"
                  strokeWidth="1.4"
                  strokeLinejoin="round"
                  fill="rgba(201,164,75,0.18)"
                />
                <path
                  d="M3 9h18M9 3 12 21 15 3M9 3l3 6 3-6"
                  stroke="var(--gold)"
                  strokeWidth="1"
                  strokeLinejoin="round"
                />
              </svg>
              <span style={{ color: 'var(--gold)' }} className="font-semibold tabular-nums">
                {balanceLoading || balance === null ? '—' : balance}
              </span>
            </div>

            {/* Avatar */}
            <div
              className="flex items-center justify-center h-9 w-9 rounded-full font-display text-sm font-semibold select-none"
              style={{
                background: 'var(--gold-dim)',
                color: 'var(--gold)',
                border: '1px solid var(--gold)',
              }}
              title={user?.nombre ?? ''}
            >
              {initial}
            </div>
          </div>
        </div>

        {/* Nav tabs */}
        <nav className="flex items-center gap-1 sm:gap-2 overflow-x-auto mt-3">
          {NAV_ITEMS.map((item) => {
            const isActive = pathname === item.href;
            return (
              <Link
                key={item.href}
                href={item.href}
                className="px-3 py-2 text-sm whitespace-nowrap transition-colors"
                style={{
                  color: isActive ? 'var(--gold)' : 'var(--parchment-muted)',
                  borderBottom: isActive
                    ? '2px solid var(--gold)'
                    : '2px solid transparent',
                }}
              >
                {item.label}
              </Link>
            );
          })}
        </nav>
      </div>
    </header>
  );
}

export default AppHeader;
